schema.code:
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "https://faion.net/schemas/regression-test-first-bugfix-workflow.json",
  "title": "Regression-test-first bugfix workflow record",
  "type": "object",
  "required": ["alert", "red_test", "fix", "verification", "owner", "review"],
  "additionalProperties": false,
  "definitions": {
    "url": {"type": "string", "pattern": "^https://"},
    "sha": {"type": "string", "pattern": "^[0-9a-f]{7,40}$"},
    "date": {"type": "string", "pattern": "^[0-9]{4}-[0-9]{2}-[0-9]{2}$"},
    "handle": {"type": "string", "pattern": "^[a-z-]+:[a-z0-9._-]+$"}
  },
  "properties": {
    "__faion_header__": {"type": ["object", "string"]},
    "alert": {
      "type": "object",
      "required": ["kind", "url", "alert_id", "observed_outcome", "reproducing_inputs", "deterministic"],
      "additionalProperties": false,
      "properties": {
        "kind": {"type": "string", "enum": ["sentry", "datadog", "customer-ticket", "log-aggregator"]},
        "url": {"$ref": "#/definitions/url"},
        "alert_id": {"type": "string", "minLength": 1},
        "observed_outcome": {
          "type": "object",
          "required": ["kind", "value"],
          "additionalProperties": false,
          "properties": {
            "kind": {"type": "string", "enum": ["exception", "wrong-output"]},
            "value": {"type": "string", "minLength": 3}
          }
        },
        "side_effect": {"type": "string", "minLength": 3},
        "reproducing_inputs": {"type": "object", "minProperties": 1},
        "pii_substitutions": {
          "type": "array",
          "items": {
            "type": "object",
            "required": ["field", "shape"],
            "additionalProperties": false,
            "properties": {"field": {"type": "string", "minLength": 1}, "shape": {"type": "string", "minLength": 1}}
          }
        },
        "deterministic": {"const": true}
      }
    },
    "red_test": {
      "type": "object",
      "required": ["status"],
      "properties": {
        "status": {"type": "string", "enum": ["committed", "pending"]}
      },
      "if": {"properties": {"status": {"const": "committed"}}},
      "then": {
        "required": ["path", "commit", "commit_message_has_alert_url", "asserts", "red_ci_run_url", "failure_matches_alert", "stable_runs"],
        "additionalProperties": false,
        "properties": {
          "status": {"const": "committed"},
          "path": {"type": "string", "pattern": "^tests/regression/"},
          "commit": {"$ref": "#/definitions/sha"},
          "commit_message_has_alert_url": {"const": true},
          "asserts": {
            "type": "array",
            "minItems": 1,
            "items": {"type": "string", "minLength": 3, "not": {"pattern": "raises\\(\\s*(Exception|BaseException)\\s*\\)"}}
          },
          "side_effect_asserts": {"type": "array", "items": {"type": "string", "minLength": 3}},
          "red_ci_run_url": {"$ref": "#/definitions/url"},
          "failure_matches_alert": {"const": true},
          "stable_runs": {"type": "integer", "minimum": 3}
        }
      },
      "else": {
        "required": ["follow_up_ticket_url", "due_at"],
        "additionalProperties": false,
        "properties": {
          "status": {"const": "pending"},
          "follow_up_ticket_url": {"$ref": "#/definitions/url"},
          "due_at": {"$ref": "#/definitions/date"}
        }
      }
    },
    "fix": {
      "type": "object",
      "required": ["pr_url", "first_fix_commit", "diff_lines", "touches_red_test_assertions", "hotfix"],
      "additionalProperties": false,
      "properties": {
        "pr_url": {"$ref": "#/definitions/url"},
        "first_fix_commit": {"$ref": "#/definitions/sha"},
        "diff_lines": {"type": "integer", "minimum": 1},
        "touches_red_test_assertions": {"const": false},
        "hotfix": {"type": "boolean"},
        "refactor_pr_url": {"$ref": "#/definitions/url"}
      }
    },
    "verification": {
      "type": "object",
      "required": ["ci_run_url", "passed", "skipped_or_xfail"],
      "additionalProperties": false,
      "properties": {
        "ci_run_url": {"$ref": "#/definitions/url"},
        "passed": {"const": true},
        "skipped_or_xfail": {"const": false}
      }
    },
    "owner": {"$ref": "#/definitions/handle"},
    "review": {
      "type": "object",
      "required": ["merged_at", "next_review_at", "alert_resolved"],
      "additionalProperties": false,
      "properties": {
        "merged_at": {"$ref": "#/definitions/date"},
        "next_review_at": {"$ref": "#/definitions/date"},
        "alert_resolved": {"type": "boolean"},
        "outcome": {
          "type": "object",
          "required": ["reviewed_at", "regression_events_in_window", "same_signature_new_issue"],
          "additionalProperties": false,
          "properties": {
            "reviewed_at": {"$ref": "#/definitions/date"},
            "regression_events_in_window": {"type": "integer", "minimum": 0},
            "same_signature_new_issue": {"type": "boolean"}
          }
        }
      }
    }
  }
}

output-contract.example:
{
  "alert": {
    "kind": "sentry",
    "url": "https://sentry.io/organizations/acme/issues/12345/",
    "alert_id": "ACME-SHOP-12345",
    "observed_outcome": {"kind": "exception", "value": "ValidationError: amount must be positive (checkout/serializers.py)"},
    "side_effect": "an Order row is created before the serializer rejects the request",
    "reproducing_inputs": {"amount": 0.0, "locale": "tr_TR", "currency": "TRY", "cart_id": "c_8f3a"},
    "pii_substitutions": [{"field": "email", "shape": "same-domain synthetic address"}],
    "deterministic": true
  },
  "red_test": {
    "status": "committed",
    "path": "tests/regression/test_checkout_zero_amount.py",
    "commit": "a1b2c3d4e5f",
    "commit_message_has_alert_url": true,
    "asserts": ["response.status_code == 422", "'amount must be positive' in response.json()['detail']"],
    "side_effect_asserts": ["Order.objects.filter(cart_id='c_8f3a').count() == 0"],
    "red_ci_run_url": "https://github.com/acme/shop/actions/runs/76",
    "failure_matches_alert": true,
    "stable_runs": 3
  },
  "fix": {
    "pr_url": "https://github.com/acme/shop/pull/9981",
    "first_fix_commit": "b2c3d4e5f6a",
    "diff_lines": 18,
    "touches_red_test_assertions": false,
    "hotfix": false
  },
  "verification": {
    "ci_run_url": "https://github.com/acme/shop/actions/runs/77",
    "passed": true,
    "skipped_or_xfail": false
  },
  "owner": "swe:alice",
  "review": {
    "merged_at": "2026-05-24",
    "next_review_at": "2026-08-22",
    "alert_resolved": true,
    "outcome": {"reviewed_at": "2026-08-22", "regression_events_in_window": 0, "same_signature_new_issue": false}
  }
}

